// oct(name, size=16, cls="") -> inline <svg> (fill currentColor).
export function oct(name, size = 16, cls = "") {
  const b = OCT[name]; if (!b) throw new Error("octicon missing: " + name);
  return `<svg class="octicon ${cls}" viewBox="0 0 16 16" width="${size}" height="${size}" aria-hidden="true">${b}</svg>`;
}
